// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    ReentrantAttacker attacker;

    function setUp() public {
        c = new C();
        attacker = new ReentrantAttacker(c);
    }

    function testFuzz_property(uint256 depositAmount, uint256 probe) public {
        vm.assume(depositAmount > 0);
        attacker.setProbe(probe);
        vm.deal(address(attacker), depositAmount);
        vm.prank(address(attacker));
        c.deposit{value: depositAmount}();

        // withdrawAll from the attacker; during the payout the attacker re-enters
        // and reads c.credit(address(this)). In P credit is already zeroed before
        // the call; in M it still equals depositAmount.
        vm.prank(address(attacker));
        c.withdrawAll();

        assertTrue(attacker.seenCreditDuringPayout() == 0);
    }
}

contract ReentrantAttacker {
    C c;
    uint256 probe;
    uint256 seen;

    constructor(C _c) { c = _c; }
    function setProbe(uint256 p) external { probe = p; }
    function seenCreditDuringPayout() external view returns (uint256) { return seen; }

    receive() external payable {
        seen = c.credit(address(this));
        // consume the fuzzed probe so the payout path is exercised
        require(probe >= 0);
    }
}

