pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount) public {
        amount = bound(amount, 1 ether, 100 ether);
        Actor actor = new Actor(c);
        vm.deal(address(actor), amount);
        actor.doDeposit(amount);
        bool ok;
        try actor.doWithdraw() { ok = true; } catch { ok = false; }
        // General rule: if the withdraw did NOT succeed, the caller's credit is untouched;
        // if it succeeded, credit is zero AND the caller actually received the funds.
        assertTrue(ok ? c.credit(address(actor)) == 0 && address(actor).balance >= amount
                      : c.credit(address(actor)) == amount && address(c).balance == amount);
    }
}

contract Actor {
    C c;
    constructor(C c_) { c = c_; }
    function doDeposit(uint256 amt) external { c.deposit{value: amt}(); }
    function doWithdraw() external { c.withdrawAll(); }
    fallback() external payable { revert(); }
}

