pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(actor != address(c));
        vm.assume(actor != address(this));
        vm.assume(actor.code.length == 0);
        amount = bound(amount, 2, 1e30);
        vm.deal(actor, amount);
        uint256 actorBefore = actor.balance;
        vm.prank(actor);
        c.deposit{value: amount}();
        uint256 contractBefore = address(c).balance;
        vm.prank(actor);
        c.withdrawAll();
        // General rule: withdrawing all credit pays out the entire deposited amount:
        // the actor receives exactly `amount` wei and c's balance drops by exactly `amount`.
        assertTrue(
            actor.balance == actorBefore + amount &&
            address(c).balance == contractBefore - amount
        );
    }
}

