pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 amount, address actor) public {
        // admissible domain: a plain (codeless) actor, distinct from c and 0, depositing more than 1 wei
        vm.assume(actor != address(0));
        vm.assume(actor != address(c));
        vm.assume(actor.code.length == 0);
        bound(amount, 2, 1e30);

        vm.deal(actor, amount);
        vm.prank(actor);
        c.deposit{value: amount}();
        assertEq(address(c).balance, amount); // sanity of setup (setup check via eq is fine)

        vm.prank(actor);
        bool ok;
        try c.withdrawAll() { ok = true; } catch { ok = false; }

        // RULE: after withdrawAll succeeds, the contract holds no ether — the caller's full credit is paid out.
        assertTrue(ok && address(c).balance == 0);
    }
}

