pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 amount, address actor) public {
        // keep params in the admissible domain: a real, non-zero, depositor-and-amount pair
        vm.assume(actor != address(c));
        vm.assume(actor != address(0));
        amount = bound(amount, 1, type(uint256).max / 2);

        // actor deposits `amount`
        vm.deal(actor, amount);
        vm.prank(actor);
        c.deposit{value: amount}();

        // actor withdraws everything through withdrawAll (pays out to the actor's address)
        vm.prank(actor);
        c.withdrawAll();

        // General rule: after a full deposit+withdrawAll cycle the contract holds no Ether
        // from that cycle — the withdrawal must drain exactly the caller's credit.
        // The reference contract satisfies this for every input; the mutant (which never
        // decrements its internal balance on withdrawal) breaks it for withdrawing actors.
        assertTrue(address(c).balance == 0, "contract must be fully drained after withdrawAll");
    }
}
